onClick:
{{ (async()=>{try{
const kind=selCompanyDonorContactKind.selectedOptionValue;
const contact=selCompanyDonorContactToArchive.selectedOptionValue;
const target=selCompanyContactReassignTarget.selectedOptionValue;
const reason=inpCompanyDonorContactReason.text?.trim();
if(!['email','phone','address'].includes(kind)||!contact||!target||!reason){showAlert('Select a contact, destination company and reason.','warning');return;}
const rows=await qReassignCompanyContact.run();
if(rows?.[0]?.reassigned!==true)throw new Error('Reassignment was not confirmed.');
await Promise.all([qCompanyDonorContacts.run(),qCompanyDonorAddresses.run(),qCompanyContacts.run(),qCompanyReassignTargets.run()]);
resetWidget('selCompanyContactReassignTarget',true);
showAlert('Company contact reassigned.','success');
}catch(e){showAlert('Contact reassignment failed: '+(e?.message||e),'error');}})() }}
